/**
 * Model catalog contract. `src/data/catalog.json` is generated by `scripts/build-catalog.mjs`
 * and must match these types. 1 PoYo credit = $0.005.
 */
export type Category = 'image' | 'video';

export type FieldType = 'string' | 'integer' | 'number' | 'boolean' | 'array' | 'object';

export interface FieldSchema {
  type?: FieldType;
  enum?: (string | number | boolean)[];
  default?: unknown;
  minimum?: number;
  maximum?: number;
  minLength?: number;
  maxLength?: number;
  minItems?: number;
  maxItems?: number;
  /** e.g. "uri" — string or array items that take a media URL (upload target). */
  format?: string;
  description?: string;
  items?: FieldSchema;
  /** Set by the catalog builder when a field takes uploaded media: 'image' | 'video' | 'audio'. */
  media?: 'image' | 'video' | 'audio';
}

export interface InputSchema {
  required: string[];
  properties: Record<string, FieldSchema>;
}

export interface Example {
  /** Key in the OpenAPI examples map, e.g. "text-to-video". */
  name: string;
  summary?: string;
  input: Record<string, unknown>;
}

export interface PriceTier {
  credits: number;
  priceUSD: number;
  /** "per second" | "per image" | "per 1M tokens" | "per run" ... as in models.json */
  unit: string;
  spec?: string;
  description?: string;
  /** Structured dimensions from models.json pricingTiers[].dims (resolution, videoInput, unit...). */
  dims?: Record<string, unknown>;
  /** API model IDs this tier applies to; absent = all variants of the entry. */
  appliesTo?: string[];
}

export interface Variant {
  /** API model ID sent as `model` in POST /api/generate/submit. */
  model: string;
  /** Short human label, e.g. "Standard", "Fast", "Edit". */
  label: string;
  schema: InputSchema;
  examples: Example[];
  pricing: PriceTier[];
  docUrl?: string;
}

export interface CatalogModel {
  /** models.json id, e.g. "seedance-2-5-flash". */
  id: string;
  name: string;
  provider: string;
  icon?: string;
  thumbnail?: string;
  category: Category;
  tasks: string[];
  description: string;
  isNew?: boolean;
  featured?: boolean;
  /** Position in models.json (newest first) — use for "New" ordering. */
  order: number;
  defaultVariant: string;
  variants: Variant[];
  /** https://poyo.ai/models/<id> */
  pageUrl: string;
}

export interface Catalog {
  generatedAt: string;
  apiBase: string;
  models: CatalogModel[];
}
